SELECT analytics_order_facts.category, SUM(analytics_order_facts.net_revenue) AS net_revenue FROM analytics_order_facts WHERE analytics_order_facts.year = 2025 AND analytics_order_facts.month = 4 AND analytics_order_facts.region = 'North' AND analytics_order_facts.channel = 'online' AND analytics_order_facts.customer_segment = 'small_business' GROUP BY analytics_order_facts.category ORDER BY net_revenue DESC, analytics_order_facts.category ASC LIMIT 12
